interface RuleReview { from: PackagePin; to: PackagePin; pinVersion: number; migration: MigrationPreview | null; previewHash: string }
type EditorTab = "package" | "map" | "fields" | "sheet" | "actions" | "computed" | "abilities" | "conditions" | "tests" | "migrations";
const tabs: EditorTab[] = ["package", "map", "fields", "sheet", "actions", "computed", "abilities", "conditions", "tests", "migrations"];
const tabGroups: readonly { id: "foundation" | "play" | "release"; tabs: readonly EditorTab[] }[] = [
  { id: "foundation", tabs: ["package", "map", "fields", "sheet"] },
  { id: "play", tabs: ["actions", "computed", "abilities", "conditions"] },
  { id: "release", tabs: ["tests", "migrations"] },
];
function groupLabel(id: typeof tabGroups[number]["id"]): string {
  return id === "foundation" ? t("Grundlagen") : id === "play" ? t("Spielregeln") : t("Prüfen & Übernehmen");
}
function tabLabel(id: EditorTab): string {
  switch (id) {
    case "package": return t("Paket");
    case "map": return t("Regelkarte");
    case "fields": return t("Attribute");
    case "sheet": return t("Bogen");
    case "actions": return t("Aktionen");
    case "computed": return t("Abgeleitet");
    case "abilities": return t("Fähigkeiten");
    case "conditions": return t("Zustände");
    case "tests": return t("Pakettests");
    case "migrations": return t("Migration");
  }
}
const packageKey = (pkg: PackagePin) => `${pkg.id}@${pkg.version}`;
const MIGRATION_NUMERIC_SOURCES = { actor: [{ id: "value", type: "number" as const, get label() { return t("bisheriger Wert"); } }], input: [] };
const MIGRATION_NUMERIC_FIELDS: readonly DraftField[] = [{ ...newField("value"), defaultValue: "1", get label() { return t("bisheriger Wert"); } }];
function navigateTabs(event: KeyboardEvent<HTMLButtonElement>, current: EditorTab, onChange: (tab: EditorTab) => void) {
  const index = tabs.indexOf(current);
  const next = event.key === "ArrowRight" ? (index + 1) % tabs.length : event.key === "ArrowLeft" ? (index + tabs.length - 1) % tabs.length : event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : -1;
  if (next < 0) return; event.preventDefault(); const id = tabs[next]!; onChange(id); document.getElementById(`rf-tab-${id}`)?.focus();
}
function tabDescription(id: EditorTab): string {
  switch (id) {
    case "package": return t("Name, Version, Kennung und Lizenz: die Grunddaten dieses Regelwerks.");
    case "map": return t("Regelkarte: das ganze Regelwerk als ein Bild, mit Verbindungen von den Attributen zu allem, was sie benutzt.");
    case "fields": return t("Attribute: die Werte, die jede Figur trägt, zum Beispiel Geschick oder Lebenspunkte.");
    case "sheet": return t("Bogen: wie die Attribute in frei verschachtelten Kategorien auf dem Charakterbogen angeordnet sind.");
    case "actions": return t("Aktionen: was eine Figur tun kann und wie dafür gewürfelt wird.");
    case "computed": return t("Abgeleitet: Werte, die sich aus Attributen ergeben, Regeln für einen gültigen Bogen und Balken wie Lebenspunkte.");
    case "abilities": return t("Fähigkeiten: was eine Figur lernen kann, mit Rang, Vorstufen, Voraussetzung, Preis und einer Wirkung auf Würfe.");
    case "conditions": return t("Zustände: was eine Figur vorübergehend belastet oder beflügelt und wie das in Würfe hineinrechnet.");
    case "tests": return t("Pakettests: feste Beispiele, die bei jeder Installation nachgerechnet werden.");
    case "migrations": return t("Migration: wie vorhandene Bögen beim Wechsel auf diese Version übernommen werden.");
  }
}
function starterDraft(authorName: string, packages: readonly RulePackage[]): RuleDraft {
  const draft = newPackage(authorName, packages);
  const attribute = draft.fields.find(f => f.type === "integer" || f.type === "number");
  const formula: FormulaDraft = attribute
    ? { kind: "binary", op: "+", left: { kind: "dice", count: "1", sides: "20", keep: "none", keepCount: "1", explode: "" }, right: { kind: "field", source: "actor", field: attribute.id } }
    : { kind: "dice", count: "1", sides: "20", keep: "none", keepCount: "1", explode: "" };
  const action: DraftAction = { localId: localKey(), id: "erste-aktion", name: "Erste Aktion", version: "1.0.0",
    disclosure: `Ein W20${attribute ? ` plus ${attribute.label}` : ""} entscheidet. Passe Würfel, Merkmal und Schwelle unten frei an dein System an.`,
    inputs: [], thresholdEnabled: true, threshold: "15", formula };
  return { ...draft, actions: [action] };
}
export function grundText(fall: RulePackageHindernis): string {
  switch (fall) {
    case "eingebaut": return t("noch gar nicht in der Bibliothek gespeichert");
    case "angeheftet": return t("gerade für diese Runde angeheftet");
    case "boegen": return t("von Figurenbögen benutzt");
    case "wuerfe": return t("in Würfen belegt");
  }
}
const UNBEKANNTER_STAND: Omit<RulePackageStand, "id" | "version"> = { genommen: false, loeschbar: false, hindernisse: ["eingebaut"] };
interface ErrorLocation { tab: EditorTab; label: string }
function locateValidationError(message: string, draft: RuleDraft): ErrorLocation | null {
  const byPrefix: [RegExp, EditorTab][] = [
    [/^package (id|name|version)\b/, "package"], [/^license\b/, "package"], [/^author\b/, "package"],
    [/^package: (author required|invalid namespaced id|requires unsupported engine|unsupported schemaVersion)/, "package"],
    [/^action (id|name|version|disclosure)\b/, "actions"], [/^action:|^threshold\b|^formula: unknown/, "actions"],
    [/^layout\b|^section\b/, "sheet"], [/^migration|^rename:|^add:|^archive:/, "migrations"],
    [/^selfTest\b/, "tests"], [/^abilit|^ability\b/, "abilities"], [/^condition/, "conditions"],
  ];
  const hit = byPrefix.find(([pattern]) => pattern.test(message));
  if (hit) return { tab: hit[1], label: tabLabel(hit[1]) };
  const quoted = /„([^\"]+)"/.exec(message)?.[1];
  const labelled = /^([^:]+):/.exec(message)?.[1]?.trim();
  if ((quoted && draft.fields.some(f => f.id === quoted)) || (labelled && draft.fields.some(f => f.label === labelled))) return { tab: "fields", label: tabLabel("fields") };
  if ((quoted && draft.actions.some(a => a.id === quoted || a.inputs.some(i => i.id === quoted))) || (labelled && draft.actions.some(a => a.inputs.some(i => i.label === labelled)))) return { tab: "actions", label: tabLabel("actions") };
  if (/^field\b/.test(message)) return { tab: "fields", label: tabLabel("fields") };
  return null;
}
function explainValidationError(message: string): string {
  const rewrites: [RegExp, string][] = [
    [/^package: invalid namespaced id$/, t("Die Paketkennung passt nicht ins Muster: nur Kleinbuchstaben und Ziffern, in mindestens zwei durch Punkt oder Bindestrich getrennten Teilen, z. B. de.meine-runde.regelwerk.")],
    [/^package name: expected nonempty string/, t("Das Paket braucht einen Namen. Trage im Reiter „Paket“ einen Namen ein, z. B. Mein Regelwerk.")],
    [/^license: expected nonempty string/, t("Die Lizenz darf nicht leer sein. Trage im Reiter „Paket“ z. B. MIT ein.")],
    [/^author: expected nonempty string/, t("Eine Urheberschaft ist leer. Trage im Reiter „Paket“ einen Namen ein oder entferne das leere Feld.")],
    [/^package: author required$/, t("Ein Regelpaket braucht mindestens eine Urheberschaft. Trage im Reiter „Paket“ mindestens eine Person ein.")],
    [/^package version: expected release version/, t("Die Paketversion muss dem Muster x.y.z folgen, z. B. 1.0.0 – drei durch Punkte getrennte Zahlen.")],
    [/^action version: expected release version/, t("Die Aktionsversion muss dem Muster x.y.z folgen, z. B. 1.0.0.")],
    [/^migration\.from: expected release version/, t("Die Ausgangsversion im Reiter „Migration“ muss dem Muster x.y.z folgen, z. B. 1.0.0.")],
    [/^action id: invalid identifier$/, t("Die Aktionskennung passt nicht ins Muster. Nur Kleinbuchstaben, Ziffern, „_“ und „-“, das erste Zeichen muss ein Buchstabe sein, z. B. angriff oder erste-hilfe. Öffne den Reiter „Aktionen“.")],
    [/^package: duplicate action id$/, t("Zwei Aktionen haben dieselbe Kennung. Vergib im Reiter „Aktionen“ für jede Aktion eine eigene Kennung.")],
    [/^section id: invalid identifier$/, t("Die Abschnittskennung passt nicht ins Muster. Nur Kleinbuchstaben, Ziffern, „_“ und „-“, das erste Zeichen muss ein Buchstabe sein. Öffne den Reiter „Bogen“.")],
    [/^layout: duplicate section id$/, t("Zwei Abschnitte haben dieselbe Kennung. Vergib im Reiter „Bogen“ unterschiedliche Abschnittskennungen.")],
    [/^layout: duplicate field reference$/, t("Ein Feld ist im selben Abschnitt doppelt eingetragen. Entferne den doppelten Eintrag im Reiter „Bogen“.")],
    [/^layout: unknown field reference$/, t("Der Bogen verweist auf ein Feld, das es nicht mehr gibt. Öffne den Reiter „Bogen“ und entferne oder ersetze den verwaisten Eintrag.")],
    [/^layout: unknown parent section$/, t("Eine Kategorie verweist auf eine Oberkategorie, die nicht mehr existiert. Wähle im Reiter „Bogen“ eine andere Oberkategorie.")],
    [/^layout: section cannot parent itself$/, t("Eine Kategorie kann nicht ihre eigene Oberkategorie sein. Wähle im Reiter „Bogen“ eine andere Ebene.")],
    [/^layout: category cycle$/, t("Die Kategorien bilden einen Kreis. Eine Unterkategorie darf nicht wieder über ihren eigenen Nachfahren liegen.")],
    [/^layout: category nesting too deep$/, t("Der Kategorienbaum ist zu tief verschachtelt. Reduziere ihn auf höchstens 16 Ebenen.")],
    [/^field: reversed range$/, t("Bei einem Attribut ist das Minimum größer als das Maximum. Öffne den Reiter „Attribute“ und stelle sicher, dass jedes Minimum kleiner oder gleich seinem Maximum ist.")],
    [/outside declared range$/, t("Ein Vorgabewert liegt außerhalb von Minimum und Maximum. Öffne den betroffenen Reiter und passe entweder den Vorgabewert oder die Grenzen an.")],
    [/invalid string length$/, t("Ein Text ist leer oder länger als das erlaubte Zeichenlimit. Öffne den betroffenen Reiter und kürze den Text oder erhöhe „Maximale Zeichen“.")],
    [/^action: result must be numeric$/, t("Das Ergebnis einer Aktion muss eine Zahl sein. Öffne den Reiter „Aktionen“ und prüfe die Formel – sie darf nicht mit einem Vergleich oder einem Text enden.")],
    [/^package: action required$/, t("Ein Regelpaket braucht mindestens eine Aktion. Lege im Reiter „Aktionen“ eine erste Aktion an.")],
    [/^formula: unknown (actor|input)\.(.+)$/, t("Die Formel verwendet ein Feld, das es nicht mehr gibt. Öffne den Reiter „Aktionen“, such die markierte Stelle in der Formel und wähle dort ein vorhandenes Feld neu aus.")],
    [/dice forbidden$/, t("In einer Versionsmigration sind Würfel nicht erlaubt, nur Berechnungen aus dem bisherigen Zahlenwert. Entferne den Würfel an der markierten Stelle in der Formel im Reiter „Migration“.")],
    [/^migration: numeric result required$/, t("Die Formel zur Zahlenumrechnung muss eine Zahl ergeben. Prüfe die Formel im betroffenen Migrationsschritt.")],
    [/knowledge predicates forbidden$/, t("Gehaltenes Wissen darf in einer Migration nicht abgefragt werden, nur der bisherige Zahlenwert. Passe die Formel im Reiter „Migration“ an.")],
    [/^migration: must target this package version from a different version$/, t("Ein Migrationsweg muss von einer anderen Version zu dieser Version führen. Ändere die Ausgangsversion im Reiter „Migration“.")],
    [/^migration: duplicate source version$/, t("Zwei Migrationswege haben dieselbe Ausgangsversion. Es darf nur einen Weg je Ausgangsversion geben. Öffne den Reiter „Migration“.")],
    [/^migration: final fields differ from target schema/, t("Nach den Migrationsschritten stimmen die Felder nicht mit dieser Version überein. Jedes neue Feld braucht einen eigenen „Hinzufügen“-Schritt, jedes entfernte Feld einen eigenen „Archivieren“-Schritt.")],
    [/^rename: identical fields$/, t("Umbenennen: Die neue Attributkennung muss sich von der bisherigen unterscheiden.")],
  ];
  return rewrites.find(([pattern]) => pattern.test(message))?.[1] ?? message;
}

export function RuleForge({ campaign, authorName, onDirty, onActivated }: { campaign: Campaign; authorName: string; onDirty(dirty: boolean): void; onActivated?: () => void }) {
  const [revision, setRevision] = useState(0), resource = useResource<RulesState>(apiPath(campaign.id, "/rules"), revision), task = useTask();
  const [selected, setSelected] = useState<string | null>(null), [draft, setDraft] = useState<RuleDraft | null>(null), [locked, setLocked] = useState(false), [dirty, setDirty] = useState(false);
  const [tab, setTab] = useState<EditorTab>("package"), [review, setReview] = useState<(RuleReview & { fingerprint: string }) | null>(null), [acknowledged, setAcknowledged] = useState(false), [notice, setNotice] = useState("");
  const [justInstalled, setJustInstalled] = useState<RulePackage | null>(null), upload = useRef<HTMLInputElement>(null);
  const [figure, setFigure] = useState<ExampleFigure | null>(null);
  const activationSection = useRef<HTMLDivElement>(null), previewSection = useRef<HTMLDivElement>(null);
  const [libraryQuery, setLibraryQuery] = useState(""), [zeigeGenommene, setZeigeGenommene] = useState(false);
  const [menu, setMenu] = useState<{ key: number; id: string; version: string; name: string; x: number; y: number } | null>(null);
  const packages = useMemo(() => { const values = resource.data?.packages ?? []; return justInstalled && !values.some(p => packageKey(p) === packageKey(justInstalled)) ? [...values, justInstalled] : values; }, [resource.data, justInstalled]);
  const stand = (item: { id: string; version: string }): Omit<RulePackageStand, "id" | "version"> => resource.data?.bibliothek?.find(row => row.id === item.id && row.version === item.version) ?? UNBEKANNTER_STAND;
  const genommene = packages.filter(item => stand(item).genommen), verfuegbar = zeigeGenommene ? packages : packages.filter(item => !stand(item).genommen);
  const sichtbar = verfuegbar.filter(item => `${item.name} ${item.id} ${item.version}`.toLocaleLowerCase().includes(libraryQuery.trim().toLocaleLowerCase()));
  const base = packages.find(p => packageKey(p) === selected) ?? packages.find(p => resource.data && packageKey(p) === packageKey(resource.data.pin)) ?? packages[0];
  const baseDraft = useMemo(() => base ? packageDraft(base) : null, [base]), current = draft ?? baseDraft;
  const validation = useMemo(() => current ? validateDraft(current) : null, [current]), pkg = validation?.valid ? validation.value : null;
  const [lastValidPkg, setLastValidPkg] = useState<RulePackage | null>(null);
  useEffect(() => { if (pkg) setLastValidPkg(pkg); }, [pkg]);
  const previewPkg = pkg ?? lastValidPkg;
  const errorLocation = useMemo(() => validation && !validation.valid && current ? locateValidationError(validation.error, current) : null, [validation, current]);
  const fingerprint = useMemo(() => pkg ? stableJson(pkg) : "", [pkg]);
  const tests = useMemo(() => pkg ? packageTestResults(pkg) : [], [pkg]), testsPass = tests.every(test => test.passed);
  const installed = pkg ? packages.find(p => packageKey(p) === packageKey(pkg)) : undefined;
  const exactInstalled = !!installed && stableJson(installed) === fingerprint, collision = !!installed && !exactInstalled;
  const editable = draft !== null && !locked, active = !!pkg && !!resource.data && packageKey(pkg) === packageKey(resource.data.pin);
  const readyReview = review?.fingerprint === fingerprint ? review : null;
  const setDirtyState = (value: boolean) => { setDirty(value); onDirty(value); };
  const clearReview = () => { setReview(null); setAcknowledged(false); setNotice(""); task.setError(""); };
  const edit = (next: RuleDraft) => { if (!editable || task.busy) return; setDraft(next); setDirtyState(true); clearReview(); };
  const canReplace = () => !dirty || window.confirm(t("Ungespeicherten Regelentwurf verwerfen? Lade ihn vorher als Datei herunter, wenn du ihn behalten möchtest."));
  const selectPackage = (next: RulePackage) => { if (!canReplace()) return; setSelected(packageKey(next)); setDraft(null); setLocked(false); setDirtyState(false); clearReview(); setLastValidPkg(null); };
  const begin = (next: RuleDraft) => { if (!canReplace()) return; setDraft(next); setLocked(false); setDirtyState(true); clearReview(); setTab("package"); setLastValidPkg(null); };
  const refresh = () => { setRevision(v => v + 1); setReview(null); setAcknowledged(false); };
  const runPreview = () => { if (!pkg) return; void task.run(async () => { setReview(null); setAcknowledged(false); setNotice(""); const result = await api<RuleReview>(apiPath(campaign.id, "/rules/preview"), { method: "POST", body: { package: pkg } }); setReview({ ...result, fingerprint }); }); };
  const activateFromMenu = (item: RulePackage) => {
    if (task.busy || !canReplace()) return;
    setSelected(packageKey(item)); setDraft(null); setLocked(false); setDirtyState(false); clearReview(); setLastValidPkg(null); setTab("package");
    void task.run(async () => { const result = await api<RuleReview>(apiPath(campaign.id, "/rules/preview"), { method: "POST", body: { package: item } }); setReview({ ...result, fingerprint: stableJson(item) }); requestAnimationFrame(() => jumpTo("publish")); });
  };
  const install = () => { if (!pkg || collision || !testsPass) return; void task.run(async () => { const result = await api<RulePackage>(apiPath(campaign.id, "/rules"), { method: "POST", body: pkg }); setJustInstalled(result); setDraft(packageDraft(result)); setSelected(packageKey(result)); setLocked(true); setDirtyState(false); setRevision(v => v + 1); setNotice(t("Paketversion installiert. Für die Runde wird sie erst durch die ausdrückliche Aktivierung wirksam.")); }); };
  const activate = () => { if (!pkg || !readyReview || !exactInstalled || active || (!!readyReview.migration?.entities.length && !acknowledged)) return; void task.run(async () => {
    try { await api(apiPath(campaign.id, "/rules/activate"), { method: "POST", body: { packageId: pkg.id, packageVersion: pkg.version, expectedVersion: readyReview.pinVersion, previewHash: readyReview.previewHash } }); }
    catch (error) { if (error instanceof ApiError && error.status === 409) { refresh(); throw new Error(t("Die Runde hat sich seit der Vorschau verändert. Prüfe die Migration erneut und bestätige die aktuelle Vorschau.")); } throw error; }
    setNotice(t("Für diese Runde ist jetzt {name} {version} aktiv.", { name: pkg.name, version: pkg.version })); setDirtyState(false); refresh(); onActivated?.();
  }); };
  const importFile = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file || !canReplace()) return; void task.run(async () => { if (file.size > RULE_LIMITS.packageBytes) throw new Error(t("Das Regelpaket darf höchstens 1 MiB groß sein.")); const next = packageDraft(parseRulePackage(await file.text())); setDraft(next); setLocked(false); setDirtyState(true); clearReview(); setTab("package"); }); };
  const nehmen = (item: RulePackage, zurueck: boolean) => { void task.run(async () => { await api(apiPath(campaign.id, zurueck ? "/rules/unarchive" : "/rules/archive"), { method: "POST", body: { packageId: item.id, packageVersion: item.version } }); setNotice(zurueck ? t("„{name} {version}“ ist wieder in der Bibliothek.", { name: item.name, version: item.version }) : t("„{name} {version}“ ist aus der Bibliothek genommen. Über „Auch genommene zeigen“ holst du es zurück.", { name: item.name, version: item.version })); refresh(); }); };
  const loeschen = (item: RulePackage) => { if (!window.confirm(t("„{name} {version}“ endgültig löschen? Diese Paketfassung verschwindet vollständig und lässt sich nicht zurückholen.", { name: item.name, version: item.version }))) return; void task.run(async () => { await api(apiPath(campaign.id, "/rules"), { method: "DELETE", body: { packageId: item.id, packageVersion: item.version } }); if (selected === packageKey(item)) setSelected(null); if (!editable && current && packageKey(current) === packageKey(item)) { setDraft(null); setLastValidPkg(null); setLocked(false); setDirtyState(false); } if (justInstalled && packageKey(justInstalled) === packageKey(item)) setJustInstalled(null); setNotice(t("„{name} {version}“ ist endgültig gelöscht.", { name: item.name, version: item.version })); refresh(); }); };
  const oeffneMenu = (item: RulePackage, x: number, y: number) => setMenu({ key: Date.now(), id: item.id, version: item.version, name: item.name, x, y });
  const menuPaket = menu ? packages.find(item => item.id === menu.id && item.version === menu.version) : undefined, menuStand = menuPaket ? stand(menuPaket) : null;
  const download = () => { if (!pkg) return; const url = URL.createObjectURL(new Blob([JSON.stringify(pkg, null, 2) + "\n"], { type: "application/json" })); const link = document.createElement("a"); link.href = url; link.download = `${pkg.id}-${pkg.version}.rules.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); };
  const jumpTo = (section: "preview" | "publish") => { const node = section === "preview" ? previewSection.current : activationSection.current; if (!node) return; const stage = node.closest<HTMLElement>(".main-stage"); if (stage) stage.scrollTo({ top: stage.scrollTop + node.getBoundingClientRect().top - stage.getBoundingClientRect().top - 20 }); else node.scrollIntoView({ block: "start" }); node.focus({ preventScroll: true }); };
  if (campaign.role !== "leitung") return <Notice>{t("Die Regelwerkstatt steht der Spielleitung zur Verfügung.")}</Notice>;
  if (resource.loading && !resource.data) return <Loading text={t("Regelpakete werden geladen …")} />;
  return <div className="rule-forge">
    <header className="rf-header"><div><span className="eyebrow">{t("Regeln für {name}", { name: campaign.name })}</span><h1><Hammer size={26} />{t("Regelwerkstatt")}</h1><p>{t("Gestalte den Charakterbogen, lege Würfe fest und probiere dein Regelwerk aus. Du entscheidest, welche geprüfte Version für die Runde gilt.")}</p></div><div className="rf-toolbar"><Button disabled={task.busy} onClick={() => begin(starterDraft(authorName, packages))}><Plus size={16} />{t("Neues Paket")}</Button><Button disabled={task.busy} onClick={() => upload.current?.click()}><Upload size={16} />{t("Paket öffnen")}</Button><input ref={upload} type="file" accept=".json,application/json" hidden onChange={importFile} disabled={task.busy} /></div></header>
    <details className="rf-starter"><summary><span><strong>{t("Mit einer Vorlage starten")}</strong><small>{t("ChronicleHeroes · W100, Talente und ein anpassbarer Fertigkeitskatalog")}</small></span></summary><ChronicleHeroesTemplate disabled={task.busy} onCreate={template => begin(packageDraft(template))} /></details>
    {resource.error ? <Notice error>{resource.error} <Button disabled={task.busy} onClick={refresh}>{t("Erneut laden")}</Button></Notice> : null}{task.error ? <Notice error>{task.error}</Notice> : null}{notice ? <Notice>{notice}</Notice> : null}
    <div className="rf-workspace"><aside className="rf-catalog" aria-label={t("Installierte Regelpakete")}><div className="rf-section-heading"><h2><BookOpen size={18} />{t("Bibliothek")}</h2><Button variant="quiet" disabled={task.busy} onClick={refresh} aria-label={t("Paketbibliothek aktualisieren")}>↻</Button></div>
      <p className="rf-help">{t("Installierte Versionen bleiben unveränderlich.")}</p><label className="rf-library-search"><Search size={15} aria-hidden="true" /><input type="search" value={libraryQuery} aria-label={t("Regelpaket suchen")} placeholder={t("Name, Kennung oder Version")} onChange={event => setLibraryQuery(event.target.value)} /></label>
      <details className="rf-library-help"><summary>{t("Pakete verwalten")}</summary><p className="rf-help">{t("Über das Menü am Eintrag kannst du Versionen aktivieren, aus der Bibliothek nehmen oder zurückholen. Endgültiges Löschen ist nur möglich, wenn nichts mehr darauf verweist.")}</p></details>
      {genommene.length ? <Button variant="quiet" aria-pressed={zeigeGenommene} disabled={task.busy} onClick={() => setZeigeGenommene(v => !v)}>{t("Auch genommene zeigen ({anzahl})", { anzahl: genommene.length })}</Button> : null}
      {sichtbar.map(item => <div className="rf-catalog-row" key={packageKey(item)}><button type="button" className={`rf-catalog-item ${!editable && current?.id === item.id && current.version === item.version ? "is-selected" : ""}`} disabled={task.busy} aria-pressed={!editable && current?.id === item.id && current.version === item.version} onClick={() => selectPackage(item)} onContextMenu={event => { event.preventDefault(); event.stopPropagation(); oeffneMenu(item, event.clientX, event.clientY); }} onKeyDown={event => { if (event.key !== "ContextMenu" && !(event.shiftKey && event.key === "F10")) return; event.preventDefault(); event.stopPropagation(); const rand = event.currentTarget.getBoundingClientRect(); oeffneMenu(item, rand.left, rand.bottom + 4); }}><strong>{item.name}</strong><span>{stand(item).genommen ? t("{version} · Aus der Bibliothek genommen", { version: item.version }) : resource.data && packageKey(item) === packageKey(resource.data.pin) ? t("{version} · Aktiv in dieser Runde", { version: item.version }) : t("{version} · Installiert", { version: item.version })}</span><small>{item.id}</small></button><Button variant="quiet" className="rf-catalog-menu" disabled={task.busy} aria-label={t("Paket {name} {version} verwalten", { name: item.name, version: item.version })} aria-haspopup="menu" onClick={event => { const bounds = event.currentTarget.getBoundingClientRect(); oeffneMenu(item, bounds.left, bounds.bottom + 4); }}><MoreHorizontal size={17} /></Button></div>)}
      {!packages.length ? <p>{t("Noch kein Paket geladen. Du kannst einen Entwurf anlegen oder eine Paketdatei öffnen.")}</p> : null}{packages.length && !verfuegbar.length ? <p>{t("Alle Pakete sind aus der Bibliothek genommen. Über den Schalter oben werden sie wieder sichtbar.")}</p> : null}{verfuegbar.length > 0 && !sichtbar.length ? <div className="rf-search-empty" role="status"><p>{t("Kein Regelpaket gefunden.")}</p><Button variant="quiet" onClick={() => setLibraryQuery("")}>{t("Suche zurücksetzen")}</Button></div> : null}
      {menu && menuPaket && menuStand ? <MapContextMenu key={menu.key} label={`${menuPaket.name} ${menuPaket.version}`} popup={{ x: menu.x, y: menu.y, onDismiss: () => setMenu(null) }} actions={[{ id: "aktivieren", label: resource.data && packageKey(menuPaket) === packageKey(resource.data.pin) ? t("Bereits für diese Runde aktiv") : menuStand.genommen ? t("Zum Aktivieren zuerst in die Bibliothek zurückholen") : t("Für diese Runde aktivieren …"), disabled: task.busy || menuStand.genommen || (!!resource.data && packageKey(menuPaket) === packageKey(resource.data.pin)), onSelect: () => activateFromMenu(menuPaket) }, { id: "nehmen", label: menuStand.genommen ? t("Wieder in die Bibliothek") : t("Aus der Bibliothek nehmen"), onSelect: () => nehmen(menuPaket, menuStand.genommen) }, { id: "loeschen", danger: true, disabled: !menuStand.loeschbar, label: menuStand.loeschbar ? t("Endgültig löschen …") : t("Endgültig löschen — geht nicht: {grund}", { grund: menuStand.hindernisse.map(grundText).join(", ") }), onSelect: () => loeschen(menuPaket) }]} /> : null}
    </aside><section className="rf-editor" aria-label={t("Regelpaket")}><FormulaExampleContext.Provider value={figure}>
      {current ? <><div className="rf-section-heading"><div><h2>{current.name || t("Unbenanntes Regelpaket")}</h2><span className="rf-help">{!editable ? t("Installierte Version · schreibgeschützt · {version}", { version: current.version }) : dirty ? t("Ungespeicherter Entwurf · {version}", { version: current.version }) : t("Entwurf · {version}", { version: current.version })}</span></div><div className="rf-toolbar">{!editable && pkg ? <Button disabled={task.busy} onClick={() => { try { begin(forkPackage(pkg, packages)); } catch (error) { task.setError(errorText(error)); } }}>{t("Neue Version erstellen")}</Button> : null}<Button disabled={!pkg || task.busy} onClick={download}><Download size={15} />{t("Paketdatei")}</Button></div></div>
        <div className="rf-overview" aria-label={t("Die Figur in diesem Regelwerk")}><button type="button" onClick={() => setTab("fields")}><strong>{current.fields.length}</strong><span>{t("Attribute")}<small>{t("Werte der Figur")}</small></span><ArrowRight size={14} aria-hidden="true" /></button><button type="button" onClick={() => setTab("actions")}><strong>{current.actions.length}</strong><span>{t("Aktionen")}<small>{t("Würfe am Tisch")}</small></span><ArrowRight size={14} aria-hidden="true" /></button><button type="button" onClick={() => setTab("tests")}><strong>{current.selfTests.length}</strong><span>{t("Pakettests")}<small>{!pkg ? t("Entwurf prüfen") : !testsPass ? t("Abweichung gefunden") : current.selfTests.length ? t("Alle bestanden") : t("Beispiele festhalten")}</small></span><ArrowRight size={14} aria-hidden="true" /></button></div>
        <div className="rf-next-step"><div><strong>{t("Nächster Schritt")}</strong><span>{!pkg || collision || !testsPass ? t("Behebe die markierte Stelle, bevor du diese Version übernimmst.") : !editable ? t("Erkunde die Regeln oder erstelle eine neue Version zum Bearbeiten.") : !tests.length ? t("Probiere einen Wurf aus und speichere ihn als Pakettest.") : t("Prüfe die Auswirkungen auf vorhandene Figuren und übernimm die Version.")}</span></div><div className="rf-toolbar">{!pkg || collision || !testsPass ? <Button variant="quiet" onClick={() => { if (!testsPass) setTab("tests"); else if (collision) setTab("package"); else if (errorLocation) setTab(errorLocation.tab); else jumpTo("publish"); }}>{t("Prüfstelle öffnen")}<ArrowRight size={14} /></Button> : <Button variant="quiet" onClick={() => jumpTo(editable && tests.length ? "publish" : "preview")}>{editable && tests.length ? t("Zur Übernahme") : t("Zur Testtafel")}<ArrowRight size={14} /></Button>}</div></div>
        <div className="rf-tabs rf-grouped-tabs" role="tablist" aria-label={t("Regelpaket bearbeiten")}>{tabGroups.map(group => <div className="rf-tab-group" key={group.id} role="presentation"><span className="rf-tab-group-label">{groupLabel(group.id)}</span><div role="presentation">{group.tabs.map(id => <button key={id} type="button" role="tab" aria-selected={tab === id} aria-controls={`rf-panel-${id}`} id={`rf-tab-${id}`} tabIndex={tab === id ? 0 : -1} title={tabDescription(id)} onKeyDown={event => navigateTabs(event, id, setTab)} onClick={() => setTab(id)}>{id === "tests" && current.selfTests.length ? t("{name} ({anzahl})", { name: tabLabel(id), anzahl: current.selfTests.length }) : tabLabel(id)}{errorLocation?.tab === id ? <TriangleAlert size={12} aria-label={t("Betrifft vermutlich den aktuellen Fehler")} /> : null}</button>)}</div></div>)}</div>
        <p className="rf-tab-description">{tabDescription(tab)}</p>{!editable ? <p className="rf-readonly-help">{t("Du kannst alle Einträge ansehen. Zum Ändern erstelle oben eine neue Version.")}</p> : null}
        <fieldset className="rf-editor-fields" disabled={!["actions", "map", "fields", "abilities", "conditions"].includes(tab) && (!editable || task.busy)}><div role="tabpanel" id={`rf-panel-${tab}`} aria-labelledby={`rf-tab-${tab}`}>
          {tab === "package" ? <><PackageEditor draft={current} onChange={edit} />{pkg ? <RuleAttribution pkg={pkg} /> : null}{current.attribution ? <AttributionEditor value={current.attribution} onChange={attribution => edit({ ...current, attribution })} /> : null}</> : null}
          {tab === "map" ? <RuleMap draft={current} disabled={!editable || task.busy} onChange={edit} onOpen={setTab} /> : null}
          {tab === "fields" ? <FieldList title={t("Attribute")} fields={current.fields} disabled={!editable || task.busy} onChange={fields => edit({ ...current, fields, sections: current.sections.map(s => ({ ...s, fieldKeys: s.fieldKeys.filter(id => fields.some(f => f.localId === id)) })) })} /> : null}
          {tab === "sheet" ? <SheetEditor fields={current.fields} sections={current.sections} onChange={sections => edit({ ...current, sections })} /> : null}
          {tab === "actions" ? <RuleActionEditor draft={current} disabled={!editable || task.busy} onChange={actions => edit({ ...current, actions })} /> : null}{tab === "computed" ? <RuleDeclarativeEditor draft={current} onChange={edit} /> : null}{tab === "abilities" ? <RuleAbilityEditor draft={current} disabled={!editable || task.busy} onChange={edit} /> : null}{tab === "conditions" ? <RuleConditionEditor draft={current} disabled={!editable || task.busy} onChange={edit} /> : null}
          {tab === "tests" ? <><h3>{t("Pakettests")}</h3><p>{t("Speichere Beispiele aus der Testtafel als feste Erwartung. Bei der Installation werden alle enthaltenen Tests ausgeführt.")}</p>{!current.selfTests.length ? <p className="rf-help">{t("Noch keine Pakettests. Unten auf der Testtafel kannst du für jede Figur ein Beispiel speichern.")}</p> : <div className="rf-test-list">{current.selfTests.map((test, i) => <article className="rf-card" key={i}><div className="rf-section-heading"><h4>{test.name}</h4><Button variant="quiet" aria-label={t("Pakettest {name} entfernen", { name: test.name })} onClick={() => edit({ ...current, selfTests: current.selfTests.filter((_, n) => n !== i) })}><Trash2 size={15} />{t("Entfernen")}</Button></div><p>{t("{kennung} · Erwartet {erwartet} · {stand}", { kennung: test.actionId, erwartet: test.expectedTotal, stand: tests[i]?.passed ? t("Bestanden") : tests[i]?.error ?? (tests[i]?.actual === undefined ? t("Paket noch nicht gültig") : t("Ergebnis {wert} weicht ab", { wert: String(tests[i]!.actual) })) })}</p><details><summary>{t("Gespeicherte Beispielwerte")}</summary><dl className="rf-value-list"><dt>{t("Würfelstart")}</dt><dd>{test.context.seed}</dd>{Object.entries(test.context.actor).map(([id, value]) => <div key={id}><dt>{id}</dt><dd>{String(value)}</dd></div>)}</dl><p>{t("{anzahl} gehaltene Beispielpassagen", { anzahl: test.context.knowledge.passages.length })}</p></details></article>)}</div>}</> : null}
          {tab === "migrations" ? <MigrationEditor draft={current} packages={packages} onChange={migrations => edit({ ...current, migrations })} /> : null}
        </div></fieldset>
        <div className="rf-validation" aria-live="polite">{validation && !validation.valid ? <Notice error><p>{explainValidationError(validation.error)}</p>{errorLocation && errorLocation.tab !== tab ? <Button variant="quiet" onClick={() => setTab(errorLocation.tab)}>{t("Zum Reiter „{name}“ springen", { name: errorLocation.label })}</Button> : null}</Notice> : <p><Check size={16} />{tests.length ? t("Paketstruktur, Feldtypen und Formeln gültig · {bestanden} von {gesamt} Pakettests bestanden.", { bestanden: tests.filter(test => test.passed).length, gesamt: tests.length }) : t("Paketstruktur, Feldtypen und Formeln gültig.")}</p>}{collision ? <Notice error>{t("Diese Kennung und Version sind bereits mit anderem Inhalt installiert. Wähle eine neue Version.")}</Notice> : null}</div>
        <div className="rf-publish" ref={activationSection} tabIndex={-1}><h3>{t("Prüfen und übernehmen")}</h3><p>{t("Die Installation speichert eine unveränderliche Version. Die Aktivierung wechselt das Regelwerk dieser Runde und übernimmt die zuvor geprüften Feldänderungen.")}</p><div className="rf-toolbar"><Button disabled={!pkg || !testsPass || collision || task.busy || active} onClick={runPreview}><FlaskConical size={16} />{readyReview ? t("Vorschau erneuern") : t("Aktivierung prüfen")}</Button><Button variant="primary" disabled={!pkg || !testsPass || collision || exactInstalled || task.busy} onClick={install}>{exactInstalled ? t("Version ist installiert") : t("Version installieren")}</Button></div>{active ? <p className="rf-help">{t("Diese Paketversion ist bereits aktiv.")}</p> : null}{readyReview ? <ReviewPanel review={readyReview} acknowledged={acknowledged} onAcknowledge={setAcknowledged} disabled={task.busy} /> : null}{readyReview ? <Button variant="primary" disabled={task.busy || !exactInstalled || active || (!!readyReview.migration?.entities.length && !acknowledged)} onClick={activate}>{t("Geprüfte Version für diese Runde aktivieren")}</Button> : null}{readyReview && !exactInstalled ? <p className="rf-help">{t("Installiere zuerst genau diese geprüfte Version. Die Vorschau bleibt für die anschließende Aktivierung erhalten.")}</p> : null}</div>
      </> : <EmptyState title={t("Leg dein erstes Regelpaket an.")} action={<div className="rf-toolbar"><Button onClick={() => begin(starterDraft(authorName, packages))}><Plus size={16} />{t("Neues Paket beginnen")}</Button><Button onClick={() => upload.current?.click()}><Upload size={16} />{t("Paketdatei öffnen")}</Button></div>}>{t("Ein Regelpaket bündelt Charakterfelder wie Kraft oder Geschick, den Aufbau des Charakterbogens und Aktionen zu einer festen Version. Eine Aktion ist ein Wurf wie „1d20 plus Geschick, Erfolg ab 15“: ein Würfel, ein Charakterwert und eine Zahl, ab der die Aktion gelingt. „Neues Paket beginnen“ legt genau so ein Beispiel an, das du danach frei umbaust.")}</EmptyState>}
    </FormulaExampleContext.Provider></section></div>
    {!pkg && lastValidPkg ? <Notice>{t("Die Testtafel unten zeigt zur Orientierung weiter die zuletzt gültige Fassung (Version {version}), statt beim Bearbeiten zu verschwinden. Dein aktueller Entwurf ist noch nicht gültig: {fehler}", { version: lastValidPkg.version, fehler: validation && !validation.valid ? explainValidationError(validation.error) : "" })}</Notice> : null}<div ref={previewSection} className="rf-preview-anchor" tabIndex={-1}><RuleForgePreview pkg={previewPkg} onFigure={setFigure} onSaveTest={editable && current && pkg && !task.busy && current.selfTests.length < 64 ? test => edit({ ...current, includeSelfTests: true, selfTests: [...current.selfTests, test] }) : undefined} /></div>
  </div>;
}
function PackageEditor({ draft, onChange }: { draft: RuleDraft; onChange(value: RuleDraft): void }) {
  return <><h3>{t("Paketangaben")}</h3><p className="rf-help">{t("Diese Angaben identifizieren das Regelpaket als Ganzes, unabhängig davon, welche Felder und Aktionen es enthält.")}</p><div className="rf-form-grid"><label>{t("Name")}<input value={draft.name} maxLength={120} required placeholder={t("z. B. Mein Regelwerk")} onChange={e => onChange({ ...draft, name: e.target.value })} /><small>{t("Der Titel, den Spielleitung und Spielende in der Bibliothek sehen.")}</small></label><label>{t("Version")}<input value={draft.version} placeholder="1.0.0" required onChange={e => onChange({ ...draft, version: e.target.value })} /><small>{t("Drei durch Punkte getrennte Zahlen (Hauptversion.Nebenversion.Fehlerbehebung), z. B. 1.0.0. Jede installierte Version ist danach unveränderlich.")}</small></label><label>{t("Paketkennung")}<input value={draft.id} maxLength={128} placeholder="de.meine-runde.regelwerk" required onChange={e => onChange({ ...draft, id: e.target.value })} /><small>{t("Namensraum mit Punkten oder Bindestrichen, ausschließlich Kleinbuchstaben und Ziffern, z. B. de.meine-runde.regelwerk.")}</small></label><label>{t("Lizenz")}<input value={draft.license} maxLength={120} required placeholder={t("z. B. MIT")} onChange={e => onChange({ ...draft, license: e.target.value })} /><small>{t("Unter welchen Bedingungen andere dieses Paket weiterverwenden dürfen, z. B. MIT oder Alle Rechte vorbehalten.")}</small></label></div><h4>{t("Urheberschaft")}</h4><p className="rf-help">{t("Wer dieses Regelwerk verfasst hat. Mindestens eine Angabe ist erforderlich.")}</p>{draft.authors.map((author, i) => <div className="rf-inline" key={i}><label>{t("Autor:in {n}", { n: i + 1 })}<input value={author} maxLength={120} required placeholder={t("Name oder Tischname")} onChange={e => onChange({ ...draft, authors: draft.authors.map((a, n) => n === i ? e.target.value : a) })} /></label><Button disabled={draft.authors.length <= 1} variant="quiet" aria-label={t("Autor:in {n} entfernen", { n: i + 1 })} onClick={() => onChange({ ...draft, authors: draft.authors.filter((_, n) => n !== i) })}><Trash2 size={15} /></Button></div>)}<Button disabled={draft.authors.length >= 32} onClick={() => onChange({ ...draft, authors: [...draft.authors, ""] })}><Plus size={15} />{t("Weitere Urheberschaft")}</Button><p className="rf-help">{t("Dieses Paket verwendet die deklarativen Regelbausteine der Engine {version}. Formeln können Werte berechnen und gehaltenes Wissen prüfen. Aktionen benötigen am Tisch eine menschliche Bestätigung.", { version: ENGINE_VERSION })}</p></>;
}
function OrderButtons({ index, length, onMove }: { index: number; length: number; onMove(delta: -1 | 1): void }) { return <span className="rf-order"><Button variant="quiet" disabled={index === 0} aria-label={t("Nach oben verschieben")} onClick={() => onMove(-1)}><ArrowUp size={14} /></Button><Button variant="quiet" disabled={index === length - 1} aria-label={t("Nach unten verschieben")} onClick={() => onMove(1)}><ArrowDown size={14} /></Button></span>; }
function SheetEditor({ fields, sections, onChange }: { fields: DraftField[]; sections: DraftSection[]; onChange(sections: DraftSection[]): void }) {
  const update = (section: DraftSection) => onChange(sections.map(s => s.localId === section.localId ? section : s));
  const isDescendant = (candidateLocalId: string, ancestorLocalId: string) => { let current = sections.find(section => section.localId === candidateLocalId)?.parentLocalId ?? null; const seen = new Set<string>(); while (current) { if (current === ancestorLocalId) return true; if (seen.has(current)) return true; seen.add(current); current = sections.find(section => section.localId === current)?.parentLocalId ?? null; } return false; };
  const remove = (section: DraftSection) => onChange(sections.filter(row => row.localId !== section.localId).map(row => row.parentLocalId === section.localId ? { ...row, parentLocalId: section.parentLocalId } : row));
  return <><div className="rf-section-heading"><h3>{t("Aufbau des Charakterbogens")}</h3><Button disabled={sections.length >= 64} onClick={() => onChange([...sections, { localId: localKey(), id: uniqueId("abschnitt", sections.map(s => s.id)), label: "Neue Kategorie", fieldKeys: [], parentLocalId: null }])}><Plus size={15} />{t("Kategorie")}</Button></div><p className="rf-help">{t("Kategorien können beliebig ineinander liegen. Lege z. B. „Fähigkeiten“ an und darunter „Handeln“, „Wissen“ und „Soziales“. Character Sheet und Vorlageneditor übernehmen diese Struktur automatisch.")}</p>
    {sections.map((section, index) => { const assignedElsewhere = new Set(sections.filter(row => row.localId !== section.localId).flatMap(row => row.fieldKeys)); return <article className="rf-card" key={section.localId}><div className="rf-section-heading"><h4>{section.label}</h4><span className="rf-toolbar"><OrderButtons index={index} length={sections.length} onMove={delta => onChange(moveItem(sections, index, delta))} /><Button variant="quiet" aria-label={t("Abschnitt {name} entfernen", { name: section.label })} onClick={() => remove(section)}><Trash2 size={15} /></Button></span></div><div className="rf-form-grid"><label>{t("Titel")}<input value={section.label} maxLength={120} onChange={e => update({ ...section, label: e.target.value })} /></label><label>{t("Abschnittskennung")}<input value={section.id} maxLength={96} onChange={e => update({ ...section, id: e.target.value })} /><small>{t("Nur zur internen Zuordnung, z. B. werte. Nur Kleinbuchstaben, Ziffern, „_“ und „-“, beginnend mit einem Buchstaben.")}</small></label><label>{t("Oberkategorie")}<select value={section.parentLocalId ?? ""} onChange={e => update({ ...section, parentLocalId: e.target.value || null })}><option value="">{t("Keine · oberste Ebene")}</option>{sections.filter(candidate => candidate.localId !== section.localId && !isDescendant(candidate.localId, section.localId)).map(candidate => <option key={candidate.localId} value={candidate.localId}>{candidate.label}</option>)}</select><small>{t("Unterkategorien werden im Charakterbogen automatisch innerhalb ihrer Oberkategorie dargestellt.")}</small></label></div>
      <ol className="rf-layout-fields">{section.fieldKeys.map((key, i) => <li key={key}><span>{fields.find(f => f.localId === key)?.label ?? t("Entferntes Attribut")}</span><OrderButtons index={i} length={section.fieldKeys.length} onMove={delta => update({ ...section, fieldKeys: moveItem(section.fieldKeys, i, delta) })} /><Button variant="quiet" aria-label={t("Attribut aus Abschnitt entfernen")} onClick={() => update({ ...section, fieldKeys: section.fieldKeys.filter(k => k !== key) })}><Trash2 size={14} /></Button></li>)}</ol>
      <label>{t("Attribut zuordnen")}<select value="" onChange={e => { if (e.target.value) update({ ...section, fieldKeys: [...section.fieldKeys, e.target.value] }); }}><option value="">{t("Attribut auswählen …")}</option>{fields.filter(f => !section.fieldKeys.includes(f.localId) && !assignedElsewhere.has(f.localId)).map(f => <option key={f.localId} value={f.localId}>{t("{name} ({kennung})", { name: f.label, kennung: f.id })}</option>)}</select></label>
    </article>; })}</>;
}
function stepName(kind: DraftMigrationStep["kind"]): string { switch (kind) { case "rename": return t("Umbenennen"); case "add": return t("Hinzufügen"); case "archive": return t("Archivieren"); default: return t("Zahl umrechnen"); } }
function MigrationEditor({ draft, packages, onChange }: { draft: RuleDraft; packages: readonly RulePackage[]; onChange(migrations: DraftMigration[]): void }) {
  const sources = packages.filter(p => p.id === draft.id && p.version !== draft.version), update = (next: DraftMigration) => onChange(draft.migrations.map(m => m.localId === next.localId ? next : m));
  return <><div className="rf-section-heading"><h3>{t("Charakterfelder migrieren")}</h3><Button disabled={draft.migrations.length >= 64} onClick={() => onChange([...draft.migrations, { localId: localKey(), from: sources.find(p => !draft.migrations.some(m => m.from === p.version))?.version ?? "", steps: [] }])}><Plus size={15} />{t("Migrationsweg")}</Button></div><p>{t("Jeder Weg beschreibt einen direkten Wechsel von einer früheren Version zu {version}. Schritte werden der Reihe nach angewendet. Entfernte Werte müssen ausdrücklich archiviert und neue Felder ausdrücklich hinzugefügt werden.", { version: draft.version || t("dieser Version") })}</p><p className="rf-help">{t("Bei vorhandenen Charakterbögen ist auch für unveränderte Felder ein Weg ohne Schritte erforderlich. Ein Wechsel zu einer anderen Paketkennung kann vorhandene Bögen nicht übernehmen. Bereits gespeicherte Würfe behalten ihre ursprünglichen Regeln.")}</p><datalist id="rf-migration-versions">{sources.map(p => <option key={p.version} value={p.version} />)}</datalist>{draft.migrations.map(migration => <article className="rf-card" key={migration.localId}><div className="rf-section-heading"><h4>{t("{ausgang} → {ziel}", { ausgang: migration.from || t("Ausgangsversion wählen"), ziel: draft.version })}</h4><Button variant="quiet" aria-label={t("Migrationsweg von {version} entfernen", { version: migration.from })} onClick={() => onChange(draft.migrations.filter(m => m.localId !== migration.localId))}><Trash2 size={15} /></Button></div><label>{t("Ausgangsversion")}<input value={migration.from} list="rf-migration-versions" placeholder="1.0.0" onChange={e => update({ ...migration, from: e.target.value })} /><small>{t("Die frühere Paketversion, aus der Bögen übernommen werden, z. B. 1.0.0, muss sich von {version} unterscheiden.", { version: draft.version || t("dieser Version") })}</small></label>{sources.find(p => p.version === migration.from) ? <p className="rf-help">{t("Ausgangsfelder: {ausgang}. Zielfelder: {ziel}.", { ausgang: Object.keys(sources.find(p => p.version === migration.from)!.fields).join(", ") || t("keine"), ziel: draft.fields.map(f => f.id).join(", ") || t("keine") })}</p> : <p className="rf-help">{t("Diese Ausgangsversion ist noch nicht in der Bibliothek. Die tatsächlichen Charakterwerte prüft die Aktivierungsvorschau.")}</p>}{!migration.steps.length ? <p>{t("Keine Feldänderungen. Vorhandene Werte bleiben erhalten, sofern sie vollständig zum Zielbogen passen.")}</p> : null}{migration.steps.map((step, index) => <MigrationStepEditor key={step.localId} step={step} index={index} length={migration.steps.length} onChange={next => update({ ...migration, steps: migration.steps.map(s => s.localId === step.localId ? next : s) })} onRemove={() => update({ ...migration, steps: migration.steps.filter(s => s.localId !== step.localId) })} onMove={delta => update({ ...migration, steps: moveItem(migration.steps, index, delta) })} />)}<div className="rf-toolbar">{(["rename", "add", "archive", "numeric"] as const).map(kind => <Button key={kind} disabled={migration.steps.length >= 128} onClick={() => update({ ...migration, steps: [...migration.steps, migrationStepDraft(kind === "rename" ? { kind, from: "", to: "" } : kind === "add" ? { kind, field: "", value: 0 } : kind === "archive" ? { kind, field: "" } : { kind, field: "", expression: "actor.value" })] })}><Plus size={14} />{stepName(kind)}</Button>)}</div></article>)}</>;
}
function MigrationStepEditor({ step, index, length, onChange, onRemove, onMove }: { step: DraftMigrationStep; index: number; length: number; onChange(step: DraftMigrationStep): void; onRemove(): void; onMove(delta: -1 | 1): void }) {
  return <fieldset className="rf-migration-step"><legend>{t("{n}. {schritt}", { n: index + 1, schritt: stepName(step.kind) })}</legend><div className="rf-toolbar"><OrderButtons index={index} length={length} onMove={onMove} /><Button variant="quiet" onClick={onRemove} aria-label={t("Migrationsschritt {n} entfernen", { n: index + 1 })}><Trash2 size={15} /></Button></div>{step.kind === "rename" ? <div className="rf-form-grid"><label>{t("Bisherige Attributkennung")}<input value={step.from} onChange={e => onChange({ ...step, from: e.target.value })} /><small>{t("Wie das Attribut in der Ausgangsversion heißt.")}</small></label><label>{t("Neue Attributkennung")}<input value={step.to} onChange={e => onChange({ ...step, to: e.target.value })} /><small>{t("Wie das Attribut im Reiter „Attribute“ jetzt heißt.")}</small></label></div> : <label>{t("Attributkennung")}<input value={step.field} onChange={e => onChange({ ...step, field: e.target.value })} /><small>{step.kind === "archive" ? t("Muss in der Ausgangsversion vorhanden sein.") : t("Muss im Reiter „Attribute“ dieser Version vorhanden sein.")}</small></label>}{step.kind === "add" ? <div className="rf-form-grid"><label>{t("Werttyp")}<select value={step.type} onChange={e => { const type = e.target.value as FormulaType; onChange({ ...step, type, value: type === "number" ? "0" : type === "boolean" ? "false" : "" }); }}><option value="number">{t("Zahl")}</option><option value="string">{t("Text")}</option><option value="boolean">{t("Wahr / falsch")}</option></select></label><label>{t("Wert für bestehende Charaktere")}{step.type === "boolean" ? <select value={step.value} onChange={e => onChange({ ...step, value: e.target.value })}><option value="false">{t("Falsch")}</option><option value="true">{t("Wahr")}</option></select> : <input type={step.type === "number" ? "number" : "text"} step="any" value={step.value} onChange={e => onChange({ ...step, value: e.target.value })} />}<small>{t("Diesen Wert erhalten Charaktere, die dieses neue Feld noch nicht haben.")}</small></label></div> : null}{step.kind === "numeric" ? <FormulaField label={t("Neuer Zahlenwert")} help={t("@value ist der bisherige Zahlenwert dieses Attributs, zum Beispiel @value * 2.")} value={draftExpression(step)} onChange={expression => onChange({ ...step, expression })} sources={MIGRATION_NUMERIC_SOURCES} fields={MIGRATION_NUMERIC_FIELDS} allowDice={false} allowKnowledge={false} /> : null}</fieldset>;
}
function ReviewPanel({ review, acknowledged, onAcknowledge, disabled }: { review: RuleReview; acknowledged: boolean; onAcknowledge(value: boolean): void; disabled: boolean }) {
  return <section className="rf-review" aria-label={t("Geprüfte Aktivierung")}><h4>{t("Vorschau: {von} → {nach}", { von: review.from.version, nach: review.to.version })}</h4><p>{t("{von} → {nach}", { von: review.from.id, nach: review.to.id })}</p>{review.migration ? <><p>{t("{anzahl} vorhandene Charakterbögen geprüft.", { anzahl: review.migration.entities.length })}</p>{review.migration.entities.map(entity => <details key={entity.id}><summary>{t("Charakter {kennung} · {anzahl} Änderungen", { kennung: entity.id, anzahl: entity.changes.length })}</summary><div className="rf-table-scroll"><table><caption>{t("Geprüfte Feldwerte")}</caption><thead><tr><th>{t("Feld")}</th><th>{t("Vorher")}</th><th>{t("Nachher")}</th><th>{t("Archiviert")}</th></tr></thead><tbody>{[...new Set([...Object.keys(entity.before), ...Object.keys(entity.after), ...Object.keys(entity.archived)])].map(field => <tr key={field}><th>{field}</th><td>{Object.hasOwn(entity.before, field) ? String(entity.before[field]) : "—"}</td><td>{Object.hasOwn(entity.after, field) ? String(entity.after[field]) : "—"}</td><td>{Object.hasOwn(entity.archived, field) ? String(entity.archived[field]) : "—"}</td></tr>)}</tbody></table></div>{entity.changes.length ? <ul>{entity.changes.map((change, i) => <li key={i}>{change}</li>)}</ul> : <p>{t("Keine Feldänderungen.")}</p>}</details>)}{review.migration.entities.length ? <label className="rf-check"><input type="checkbox" checked={acknowledged} disabled={disabled} onChange={e => onAcknowledge(e.target.checked)} />{t("Ich habe die Feldänderungen und archivierten Werte geprüft.")}</label> : null}</> : <p>{t("Für diese Aktivierung müssen keine vorhandenen Charakterbögen migriert werden.")}</p>}<p className="rf-help">{t("Ändern sich Paket, aktive Version oder Charakterwerte, ist vor der Aktivierung eine neue Vorschau erforderlich.")}</p></section>;
}
